"""Event creation helper: the single write path for the event table.

The legacy app/events.py writer was deleted with the old schema; payload
validation funnels through app.payloads.
"""
from datetime import date, datetime

from sqlalchemy.orm import Session

from .models import Event, Person
from .payloads import validate_event_payload

# event types that are auto-generated by the system; the rest are teacher-defined
SYSTEM_EVENT_TYPES = {
    "enrolled", "class_moved", "exam_taken", "result_changed",
}

# event types that teachers write by hand
MANUAL_EVENT_TYPES = {
    "home_visited", "talk", "tutoring", "parent_call", "note_added",
}

# auto-generated at student creation, but surfaced as a yearly event
AUTO_RECORD_EVENT_TYPES = {"birthday"}

# everything shown as a 跟进记录/事件 in lists and calendars
RECORD_EVENT_TYPES = MANUAL_EVENT_TYPES | AUTO_RECORD_EVENT_TYPES


def next_birthday_date(birth_date: date, today: date | None = None) -> date:
    """The next occurrence of the given birthday on or after `today`."""
    today = today or date.today()
    for y in (today.year, today.year + 1):
        try:
            cand = date(y, birth_date.month, birth_date.day)
        except ValueError:  # Feb 29 → Feb 28 on non-leap years
            cand = date(y, birth_date.month, 28)
        if cand >= today:
            return cand
    return cand


def create_event(db: Session, *, event_type: str, title: str, start_time: datetime,
                 end_time: datetime | None = None, location: str | None = None,
                 description: str | None = None, payload: dict | None = None,
                 attendee_ids: list | tuple = (), commit: bool = False) -> Event:
    """Single write path for events: validates the payload, links attendees."""
    ev = Event(type=event_type, title=title, start_time=start_time, end_time=end_time,
               location=location, description=description,
               payload=validate_event_payload(event_type, payload))
    if attendee_ids:
        ev.attendees = db.query(Person).filter(Person.id.in_(attendee_ids)).all()
    db.add(ev)
    if commit:
        db.commit()
    return ev
